type moduleOptionsCall struct {
	moduleID string
	pluginID string
	options  string
}

// fakeModuleBindingOptions stands in for the cmd/mellifera closure over
// module.Registry.SetBindingOptions: it records every call and replays the
// canned err. The registry write itself lives cmd-side (3.1 landed it) —
// this fake is the seam the handler contract is pinned against.
func fakeModuleBindingOptions(err error, calls *[]moduleOptionsCall) func(context.Context, string, string, json.RawMessage) error {
	return func(_ context.Context, moduleID, pluginID string, options json.RawMessage) error {
		*calls = append(*calls, moduleOptionsCall{moduleID: moduleID, pluginID: pluginID, options: string(options)})
		return err
	}
}

